// A radiolarian appears at a random free position on every bass peak, then dissolves.
// a few seconds and dissolves again. The parameters come from a JSON file in
// public/extensions/p5-forms/presets/radiolaria-swarm/.
// The browser asks for microphone access the first time.
p5 = new P5()
p5.hide()
s0.init({ src: p5.canvas })

swarm = radiolaria.swarm(p5, { preset: 'default', debug: true, draw: true })

// a.show() draws hydra's own fft meter, so the threshold can be tuned:
//   swarm.set({ threshold: 0.8, cooldown: 0.5, max: 6 })
//   swarm.load('storm')     // another parameter set
//   swarm.trigger()         // spawn one by hand

src(s0)
  .blend(src(o0).scale(1.006).rotate(0.0008), 0.45)
  .out()

// Compares the swarm parameter presets: press 1-9 to load one, 0 for the next, click to spawn.
// click to trigger a specimen by hand. The name and the level meter are drawn
// on the canvas, so a setting can be judged without reading the code.
// Start with 'silent-pulse' or 'silent-mouse' to test without a microphone.
p5 = new P5()
p5.hide()
s0.init({ src: p5.canvas })

swarm = radiolaria.swarm(p5, { preset: 'silent-pulse', debug: true })
names = ['default']
radiolaria.loadPresets().then((index) => { names = index.presets.map((x) => x.name) })

show = (text) => {
  p5.push()
  p5.noStroke()
  p5.fill(255, 220)
  p5.textSize(14)
  p5.textFont('monospace')
  p5.text(text, 12, 24)
  p5.pop()
}

p5.draw = () => {
  swarm.draw()
  show(`${swarm.preset}   1-9 load   0 next   click spawn`)
}
p5.keyPressed = () => {
  const k = Number(p5.key)
  if (Number.isNaN(k)) return
  const i = k === 0 ? (names.indexOf(swarm.preset) + 1) % names.length : k - 1
  if (names[i]) swarm.clear(false).load(names[i])
}
p5.mousePressed = () => swarm.trigger()

